/// <summary>Path data and parsed geometries for every <see cref="MaterialShapeKind"/>.</summary>
/// <remarks>
/// Path data is copied verbatim from the design source: SVG path data for <c>Shape Set</c> and
/// fillGeometry path data for <c>.Shape</c>. Only painted geometry is kept; the source's
/// unpainted component-frame rectangles are excluded because the source fills are empty.
/// Geometries are parsed once and cached; the returned instances are shared and must not be
/// mutated. <see cref="MaterialShape"/> hands them to the renderer without cloning.
/// </remarks>
public static class MaterialShapeGeometries
{
    private static readonly ConcurrentDictionary<MaterialShapeKind, Geometry> Parsed = new();
    private static readonly ConcurrentDictionary<MaterialShapeKind, string> Data = new();

